"""agnos-meta-website: builds the AGNOS presentation website from the Markdown and the images of the skill's assets
(FTR-WEB-001; ADR-WEB-001). <!-- RQ-WEB-001, RQ-WEB-003, RQ-WEB-016 / DEC-WEB-001 -->

Usage (standard library only):
  python -I build_site.py build --demo <demo repository> --out <folder> [--demo-page <perf-center.html>]

The build reads assets/content/en.md and fr.md, checks that both hold the same fields and that the template
assets/template.html uses exactly them, replaces the link addresses of the names listed in assets/site.json, read from the repository's assets/links.json (RQ-WEB-020, RQ-DOC-007), and builds one page: English in the markup, French in
a dictionary that the page's language switch applies. The demo page is copied from --demo-page with its data files, or
generated by agnos-perf-center on the demo. Exit 0: index.html, screens/ and demo/ are written into the folder and one
summary line is printed. Exit 1: one error per line on the error stream, and nothing is written.
"""
import argparse
import html
import json
import math
import re
import shutil
import struct
import subprocess
import sys
import tempfile
from pathlib import Path
from types import MappingProxyType

# RQ-WEB-003, DEC-WEB-003: the assets
SKILL_DIR = Path(__file__).resolve().parents[1]
ASSETS_DIR = SKILL_DIR / "assets"
TEMPLATE = "template.html"
CONTENT = "content"
MARKDOWN = ".md"
LANGUAGES = ("en", "fr")
SOURCE_LANGUAGE = "en"
FRENCH = "fr"
ENCODING = "utf-8"
PAGE = "index.html"
SCREENS = "screens"

# RQ-WEB-002, DEC-WEB-002: the demo page, given or generated
PERF_CENTER_SCRIPT = SKILL_DIR.parent / "agnos-perf-center" / "scripts" / "perf_center.py"
DEMO_SOURCES = ("service", "client")          # the demo's sources, as agnos-meta-demo verify reads them
GENERATOR_OPTIONS = ("--history", "--call-graph")
DEMO_FOLDER = "demo"
DEMO_PAGE_NAME = "perf-center.html"
DEMO_LINK = f"{DEMO_FOLDER}/{DEMO_PAGE_NAME}"
DEMO_LINK_NAME = "demo"

# RQ-WEB-020, DEC-WEB-008: the external link addresses, declared once
SITE_CONFIG = "site.json"
LINKS_FILE = SKILL_DIR.parents[2] / "assets" / "links.json"   # RQ-DOC-007 / DEC-DOC-001: the repository's addresses
LINKS_FILE_NAME = LINKS_FILE.name
LINKS = "links"
LINK_PREFIX = "link."
NO_LINKS = MappingProxyType({})          # read-only: a field rendered without declared links
DEMO_DATA_SUFFIXES = (".json", ".data.js")
DEMO_COPIED, DEMO_GENERATED = "copied", "generated"
PROCESS = "agnos-process"

# RQ-WEB-006: French no-break spaces
NBSP = " "
NARROW_NBSP = " "

# RQ-WEB-019, DEC-WEB-007: the capture ratio of the screens and its tolerance
PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"
PNG_HEADER = struct.Struct(">II")        # width, height: the first 8 bytes of the IHDR chunk
PNG_HEADER_OFFSET = len(PNG_SIGNATURE) + 8   # after the signature, the chunk length and its type
SHOT_WIDTH = 1920
SHOT_HEIGHT = 1080
SHOT_TOLERANCE = 0.005

# RQ-WEB-006: French typography
APOSTROPHE = "'"
TYPOGRAPHIC_APOSTROPHE = "’"
FRENCH_COLON = re.compile(r" :")
FRENCH_MARKS = re.compile(r" ([;?!])")

# RQ-WEB-003: the content's format
COMMENT = re.compile(r"<!--.*?-->", re.S)
SECTION = re.compile(r"^##\s+([a-z0-9-]+)\s*$")
FIELD = re.compile(r"^###\s+([a-z0-9-]+)\s*$")
FENCE = "```"
FENCE_LINE = re.compile(r"^(```)$(.*?)^(```)$", re.M | re.S)
LIST_ITEM = re.compile(r"^-\s+(\S.*)$")
IMAGE = re.compile(r"^!\[([^\]]+)\]\(([^)\s]+)\)$")   # RQ-WEB-017, RQ-WEB-011: an image enlarged on click, without link
INLINE = re.compile(r"`([^`]+)`|\*\*([^*]+)\*\*|\*([^*]+)\*|\[([^\]]+)\]\(([^)\s]+)\)")
VARIABLE = re.compile(r"\{\{([a-z0-9.-]+)\}\}")
HARD_BREAK = "\\"
LINE_BREAK = "<br>"
CODE_MARK = re.compile(r"==(.+?)==")   # RQ-WEB-018: a highlighted part of a code block
PATH_LINE = "@"            # an index excerpt's document line, dimmed
LABELS_SECTION = "labels."

# DEC-WEB-003: the template's slots
SLOT = re.compile(r'(<(?P<tag>[a-z0-9]+)\b[^>]*?\sdata-i18n="(?P<key>[^"]+)"[^>]*>)(</(?P=tag)>)')
ANY_SLOT = re.compile(r'\sdata-i18n="([^"]+)"')
ATTRIBUTE_SLOT = re.compile(r'\sdata-i18n-attr="(?P<name>[a-z-]+)=(?P<key>[a-z0-9.-]+)"')
TEMPLATE_VALUE = re.compile(r"\{\{v:([a-z0-9.-]+)\}\}")
TAG = re.compile(r"<[^>]+>")
FR_MARKER = "/*@FR@*/{}"
LESS_THAN = "<"
LESS_THAN_ESCAPE = "\\u003c"

# RQ-WEB-015, DEC-WEB-005: the design system, the Performance Center's tokens and the site's layer
PERF_CENTER_TOKENS = SKILL_DIR.parent / "agnos-perf-center" / "assets" / "tokens.json"
SITE_TOKENS = ASSETS_DIR / "tokens.json"
TIERS = ("global", "semantic", "component")
GLOBAL, SEMANTIC, COMPONENT = TIERS
THEMES = ("light", "dark")
TOKENS_MARKER = "/*@TOKENS@*/"
USED_TOKEN = re.compile(r"var\(--(?P<tier>[sc])-(?P<name>[a-z0-9-]+)\)")
MEDIA_TOKEN = re.compile(r"\{\{t:([a-z0-9-]+)\}\}")
SEMANTIC_PREFIX, COMPONENT_PREFIX = "s", "c"

KIND_TEXT, KIND_LIST, KIND_CODE, KIND_IMAGE = "text", "list", "code", "image"
REPORT = "agnos-meta-website: "


def read(path):
    """The text of a UTF-8 file. RQ-WEB-003"""
    return Path(path).read_text(encoding=ENCODING)


def escape(text):
    """Text made safe for HTML content and attributes. RQ-WEB-003"""
    return html.escape(text, quote=True)


def strip_blank(lines):
    """Lines without their leading and trailing blank lines. RQ-WEB-003"""
    while lines and not lines[0].strip():
        lines = lines[1:]
    while lines and not lines[-1].strip():
        lines = lines[:-1]
    return lines


class ContentReader:
    """Reads one content file line by line into {section.field: lines}. RQ-WEB-003, RQ-WEB-004"""

    def __init__(self, name, errors):
        self.name, self.errors = name, errors
        self.fields, self.section, self.key, self.fenced = {}, None, None, False

    def report(self, number, message):
        """One misplaced line, with its file and line number. RQ-WEB-004"""
        self.errors.append(f"{self.name}:{number}: {message}")

    def add(self, line):
        """A line of the current field, if any. RQ-WEB-003"""
        if self.key is not None:
            self.fields[self.key].append(line)

    def open_field(self, number, field):
        """A new field of the current section. RQ-WEB-003, RQ-WEB-004"""
        if self.section is None:
            self.report(number, "a field before any section")
            return
        self.key = f"{self.section}.{field}"
        if self.key in self.fields:
            self.report(number, f"{self.key} is defined twice")
        self.fields[self.key] = []

    def line(self, number, line):
        """Places one line: inside a fenced block, a heading, text or a blank line. RQ-WEB-003, RQ-WEB-004"""
        fence = line.strip() == FENCE
        if self.fenced or fence:
            self.fenced = self.fenced != fence
            self.add(line)
            return
        section_match, field_match = SECTION.match(line), FIELD.match(line)
        if section_match:
            self.section, self.key = section_match.group(1), None
        elif field_match:
            self.open_field(number, field_match.group(1))
        elif line.strip() and self.key is None:
            self.report(number, "text outside a field")
        else:
            self.add(line if line.strip() else "")


def without_comments(text):
    """The text with its comments blanked, except inside fenced blocks, whose comments are shown. RQ-WEB-003,
    RQ-WEB-018"""
    parts = FENCE_LINE.split(text)
    for index in range(0, len(parts), 4):
        parts[index] = COMMENT.sub(lambda match: "\n" * match.group(0).count("\n"), parts[index])
    return "".join(parts)


def parse(path, name, errors):
    """{section.field: lines} of one content file; misplaced text is reported with its line number. RQ-WEB-003,
    RQ-WEB-004"""
    text = without_comments(read(path))
    reader = ContentReader(name, errors)
    for number, line in enumerate(text.splitlines(), 1):
        reader.line(number, line)
    return {key: strip_blank(lines) for key, lines in reader.fields.items()}


def typography(text, language):
    """French spacing and apostrophes; other languages unchanged. RQ-WEB-006"""
    if language != FRENCH:
        return text
    text = text.replace(APOSTROPHE, TYPOGRAPHIC_APOSTROPHE)
    text = FRENCH_COLON.sub(NBSP + ":", text)
    return FRENCH_MARKS.sub(NARROW_NBSP + r"\1", text)


def inline(text, language):
    """HTML of one line: `code`, **strong**, *emphasis* and [links](address); everything else escaped. RQ-WEB-003"""
    out, position = [], 0
    for match in INLINE.finditer(text):
        out.append(escape(typography(text[position:match.start()], language)))
        code, strong, emphasis, label, address = match.groups()
        if code is not None:
            out.append("<code>" + escape(code) + "</code>")
        elif strong is not None:
            out.append("<strong>" + escape(typography(strong, language)) + "</strong>")
        elif emphasis is not None:
            out.append("<em>" + escape(typography(emphasis, language)) + "</em>")
        else:
            out.append(f'<a href="{escape(address)}">{escape(typography(label, language))}</a>')
        position = match.end()
    out.append(escape(typography(text[position:], language)))
    return "".join(out)


def replace_links(line, where, links, errors):
    """The line, each declared {{link.<name>}} replaced by its address and any other {{variable}} reported. RQ-WEB-004,
    RQ-WEB-020 / DEC-WEB-008"""
    def address(match):
        if match.group(1) in links:
            return links[match.group(1)]
        errors.append(f"{where}: unknown variable {match.group(0)}")
        return match.group(0)
    return VARIABLE.sub(address, line)


def marked(line):
    """A code line escaped, its ==parts== highlighted. RQ-WEB-018"""
    return CODE_MARK.sub(lambda match: f"<mark>{match.group(1)}</mark>", escape(line))


def code_block(lines):
    """An index excerpt: its lines kept, its document lines dimmed. RQ-WEB-003"""
    return "\n".join(f"<span>{marked(line)}</span>" if line.startswith(PATH_LINE) else marked(line)
                     for line in lines[1:-1])


def paragraph(lines, language):
    """One paragraph's HTML; a line ending in a backslash forces a line break. RQ-WEB-003"""
    parts = []
    for number, line in enumerate(lines):
        broken = line.endswith(HARD_BREAK)
        parts.append(inline(line[:-len(HARD_BREAK)].rstrip() if broken else line, language))
        if number < len(lines) - 1:
            parts.append(LINE_BREAK if broken else " ")
    return "".join(parts)


def render(key, lines, language, errors, links=NO_LINKS):
    """(kind, payload) of a field: text, list, shot (alt, src, href) or code; None on error. RQ-WEB-003, RQ-WEB-004,
    RQ-WEB-020"""
    where = f"{language}{MARKDOWN}: {key}"
    if not lines:
        errors.append(where + " is empty")
        return None
    lines = [replace_links(line, where, links, errors) for line in lines]
    if lines[0].strip() == FENCE:
        return KIND_CODE, code_block(lines)
    if any(not line.strip() for line in lines):
        errors.append(where + " holds more than one paragraph")
        return None
    lines = [line.strip() for line in lines]
    items = [LIST_ITEM.match(line) for line in lines]
    if all(items):
        return KIND_LIST, [inline(item.group(1).strip(), language) for item in items]
    if any(items):
        errors.append(where + " mixes a list and a paragraph")
        return None
    image = IMAGE.match(lines[0])
    if image and len(lines) == 1:
        return KIND_IMAGE, (typography(image.group(1), language), image.group(2))
    return KIND_TEXT, paragraph(lines, language)


def render_language(language, fields, assets, links, errors, images):
    """{key: html} of one language; a missing image is reported. RQ-WEB-003, RQ-WEB-004, RQ-WEB-020"""
    parsed = {key: render(key, lines, language, errors, links) for key, lines in fields.items()}
    rendered = {}
    for key, result in parsed.items():
        if result is not None:
            rendered[key] = field_html(language, key, result, assets, errors, images)
    return rendered


def field_html(language, key, result, assets, errors, images):
    """The HTML of one rendered field; a missing image is reported. RQ-WEB-003, RQ-WEB-004"""
    kind, payload = result
    if kind == KIND_IMAGE:
        alt, src = payload
        images.add(src)
        if not (Path(assets) / src).is_file():
            errors.append(f"{language}{MARKDOWN}: {key}: {src} does not exist")
        return f'<img src="{escape(src)}" alt="{escape(alt)}" loading="lazy">'
    if kind == KIND_LIST:
        return "".join(f"<li>{item}</li>" for item in payload)
    return payload


def read_content(assets, errors):
    """{language: {key: lines}}; a field missing from one language is reported. RQ-WEB-003, RQ-WEB-004"""
    fields = {lang: parse(Path(assets) / CONTENT / (lang + MARKDOWN), lang + MARKDOWN, errors) for lang in LANGUAGES}
    for lang in LANGUAGES:
        for other in LANGUAGES:
            for key in sorted(set(fields[other]) - set(fields[lang])):
                errors.append(f"{lang}{MARKDOWN}: {key} is missing (it is in {other}{MARKDOWN})")
    return fields


def read_links(assets, errors, links_file=LINKS_FILE):
    """{"link.<name>": address} of the names assets/site.json lists, resolved from links_file; the computed demo link
    may not be listed, a listed name absent from links_file is reported. RQ-WEB-020, RQ-DOC-007 / DEC-WEB-008,
    DEC-DOC-001"""
    config = load_json(Path(assets) / SITE_CONFIG, errors)
    addresses = load_json(links_file, errors)
    if config is None or addresses is None:
        return {}
    declared = addresses.get(LINKS, {})
    links = {}
    for name in config.get(LINKS, []):
        if name == DEMO_LINK_NAME:
            errors.append(f"{SITE_CONFIG}: link {DEMO_LINK_NAME} is computed by the build")
        elif name not in declared:
            errors.append(f"{SITE_CONFIG}: link {name} is not declared in {LINKS_FILE_NAME}")
        else:
            links[LINK_PREFIX + name] = declared[name]
    return links


def fill_template(template, source, template_values, errors):
    """(page, keys used): the English text in the slots, attributes and values of the template. RQ-WEB-003,
    RQ-WEB-004, RQ-WEB-007"""
    used = set()

    def value(match):
        if match.group(1) not in template_values:
            errors.append(f"template: unknown value {match.group(0)}")
            return match.group(0)
        return escape(template_values[match.group(1)])

    def attribute(match):
        key = match.group("key")
        used.add(key)
        if key not in source:
            errors.append(f"template: {key} has no text in the content")
            return match.group(0)
        return f'{match.group(0)} {match.group("name")}="{escape(TAG.sub("", source[key]))}"'

    def element(match):
        key = match.group("key")
        used.add(key)
        if key not in source:
            errors.append(f"template: {key} has no text in the content")
            return match.group(0)
        return match.group(1) + source[key] + match.group(4)

    page = SLOT.sub(element, ATTRIBUTE_SLOT.sub(attribute, TEMPLATE_VALUE.sub(value, template)))
    for key in sorted(set(ANY_SLOT.findall(template)) - used):
        errors.append(f"template: the element of {key} must be empty")
    return page, used


def french_dictionary(template, french):
    """The French texts of the page: element HTML and plain attribute text. RQ-WEB-007"""
    elements = set(ANY_SLOT.findall(template))
    attributes = {match.group("key") for match in ATTRIBUTE_SLOT.finditer(template)}
    data = {"html": {key: french[key] for key in sorted(elements) if key in french},
            "attr": {key: TAG.sub("", french[key]) for key in sorted(attributes) if key in french}}
    return json.dumps(data, ensure_ascii=False, separators=(",", ":")).replace(LESS_THAN, LESS_THAN_ESCAPE)


def load_json(path, errors):
    """The JSON of a file, or None when it cannot be read. RQ-WEB-015"""
    try:
        return json.loads(read(path))
    except (OSError, ValueError) as error:
        errors.append(f"{Path(path).name}: {error}")
        return None


def merge_tokens(base, layer, errors):
    """The Performance Center's tokens extended by the site's layer; a repeated name is reported. RQ-WEB-015,
    DEC-WEB-005"""
    merged = {tier: dict(base.get(tier, {})) for tier in TIERS}
    for tier in TIERS:
        for name, value in layer.get(tier, {}).items():
            if name in merged[tier]:
                errors.append(f"{SITE_TOKENS.name}: {tier} token {name} is already a Performance Center token")
            merged[tier][name] = value
    return merged


def load_design_system(errors):
    """The design system of the site: the Performance Center's tokens and the site's layer. RQ-WEB-015"""
    base, layer = load_json(PERF_CENTER_TOKENS, errors), load_json(SITE_TOKENS, errors)
    if base is None or layer is None:
        return {tier: {} for tier in TIERS}
    return merge_tokens(base, layer, errors)


def theme_values(tokens, name, errors):
    """(light, dark) values of a semantic token; a reference to no global token is reported. RQ-WEB-015"""
    ref = tokens[SEMANTIC].get(name)
    refs = ref if isinstance(ref, dict) else {theme: ref for theme in THEMES}
    values = []
    for theme in THEMES:
        if refs.get(theme) not in tokens[GLOBAL]:
            errors.append(f"design token {name} refers to {refs.get(theme)}, which is no global token")
            values.append("")
        else:
            values.append(tokens[GLOBAL][refs[theme]])
    return tuple(values)


def tokens_css(tokens, semantic, component, errors):
    """The custom properties of the given tokens, --s-<semantic> per theme and --c-<component>, in the Performance
    Center's form. RQ-WEB-015, DEC-WEB-005"""
    semantic = set(semantic)
    for name in component:
        if tokens[COMPONENT].get(name) not in tokens[SEMANTIC]:
            errors.append(f"component token {name} refers to {tokens[COMPONENT].get(name)}, which is no semantic token")
        else:
            semantic.add(tokens[COMPONENT][name])
    light, dark = [], []
    for name in sorted(semantic):
        light_value, dark_value = theme_values(tokens, name, errors)
        light.append(f"  --{SEMANTIC_PREFIX}-{name}: {light_value};")
        if dark_value != light_value:
            dark.append(f"  --{SEMANTIC_PREFIX}-{name}: {dark_value};")
    light += [f"  --{COMPONENT_PREFIX}-{name}: var(--{SEMANTIC_PREFIX}-{tokens[COMPONENT][name]});"
              for name in sorted(component) if tokens[COMPONENT].get(name) in tokens[SEMANTIC]]
    dark_block = ["  color-scheme: dark;", *dark]
    return "\n".join([":root {", "  color-scheme: light;", *light, "}", "@media (prefers-color-scheme: dark) {",
                      ':root:not([data-theme="light"]) {', *dark_block, "}", "}", ':root[data-theme="dark"] {',
                      *dark_block, "}"])


def apply_tokens(template, tokens, errors):
    """The template with the CSS of the tokens it uses at its marker and its {{t:<name>}} values filled. RQ-WEB-015,
    DEC-WEB-005"""
    semantic, component = set(), set()
    for match in USED_TOKEN.finditer(template):
        tier, name = match.group("tier"), match.group("name")
        known = tokens[SEMANTIC if tier == SEMANTIC_PREFIX else COMPONENT]
        if name not in known:
            errors.append(f"template: --{tier}-{name} is no design token")
        else:
            (semantic if tier == SEMANTIC_PREFIX else component).add(name)

    def media_value(match):
        if match.group(1) not in tokens[SEMANTIC]:
            errors.append(f"template: {match.group(0)} is no design token")
            return match.group(0)
        return theme_values(tokens, match.group(1), errors)[0]

    css = tokens_css(tokens, semantic, component, errors)
    return MEDIA_TOKEN.sub(media_value, template).replace(TOKENS_MARKER, css)


def build_page(assets, errors, tokens=None, links_file=LINKS_FILE):
    """(page, summary) built from the assets, or None when an error was found. RQ-WEB-003, RQ-WEB-004, RQ-WEB-006,
    RQ-WEB-007, RQ-WEB-015, RQ-DOC-007"""
    tokens = load_design_system(errors) if tokens is None else tokens
    template = apply_tokens(read(Path(assets) / TEMPLATE), tokens, errors)
    fields = read_content(assets, errors)
    links = read_links(assets, errors, links_file)
    images, rendered = set(), {}
    for lang in LANGUAGES:
        rendered[lang] = render_language(lang, fields[lang], assets, links, errors, images)
    template_values = {LINK_PREFIX + DEMO_LINK_NAME: DEMO_LINK, **links}
    source = rendered[SOURCE_LANGUAGE]
    page, used = fill_template(template, source, template_values, errors)
    for key in sorted(set(source) - used):
        errors.append(f"content: {key} is used by no element of the template")
    if template.count(FR_MARKER) != 1:
        errors.append("template: the French marker must appear exactly once")
    page = page.replace(FR_MARKER, french_dictionary(template, rendered[FRENCH]))
    summary = f"{len(source)} fields in each language, {len(images)} images"
    return None if errors else (page, summary)


def given_demo_page(page, errors):
    """{name: bytes} of a given demo page and its data files. RQ-WEB-002, DEC-WEB-002"""
    page = Path(page)
    if page.name != DEMO_PAGE_NAME:
        errors.append(f"--demo-page: the demo page must be named {DEMO_PAGE_NAME}, since the site links to it")
        return {}
    files = {}
    for path in [page] + [page.with_name(page.stem + suffix) for suffix in DEMO_DATA_SUFFIXES]:
        if not path.is_file():
            errors.append(f"--demo-page: {path} does not exist")
        else:
            files[path.name] = path.read_bytes()
    return files


def generated_demo_page(demo, errors):
    """{name: bytes} of the demo page generated by this working tree's agnos-perf-center, with the history and the call
    graph. RQ-WEB-002, DEC-WEB-002"""
    demo = Path(demo).resolve()
    with tempfile.TemporaryDirectory(prefix="agnos-meta-website-") as folder:
        page = Path(folder) / DEMO_PAGE_NAME
        command = [sys.executable, str(PERF_CENTER_SCRIPT), "--process", str(demo / PROCESS)]
        for source in DEMO_SOURCES:
            command += ["--sources", str(demo / source)]
        # RQ-TRC-132 (TASK-TRC-122): the graph is rebuilt in a subfolder, so neither the demo nor the site holds it
        command += [*GENERATOR_OPTIONS, "--out", str(page), "--rebuild", "--graph", str(Path(folder) / "state" / "graph.json")]
        result = subprocess.run(command, cwd=demo, capture_output=True, text=True, encoding=ENCODING, check=False)
        if result.returncode != 0:
            message = (result.stderr.strip() or result.stdout.strip()).splitlines()
            errors.append(f"agnos-perf-center failed (exit {result.returncode}): {message[-1] if message else ''}")
            return {}
        return {path.name: path.read_bytes() for path in Path(folder).iterdir() if path.is_file()}


def png_size(data):
    """(width, height) of a PNG read from its IHDR chunk, or None when the data is no PNG. RQ-WEB-019, DEC-WEB-007"""
    if not data.startswith(PNG_SIGNATURE) or len(data) < PNG_HEADER_OFFSET + PNG_HEADER.size:
        return None
    return PNG_HEADER.unpack_from(data, PNG_HEADER_OFFSET)


def screen_size_error(name, data):
    """The error of an image that is not at the capture ratio or is too narrow, or None. RQ-WEB-019, DEC-WEB-007"""
    size = png_size(data)
    divisor = math.gcd(SHOT_WIDTH, SHOT_HEIGHT)
    expected = f"{SHOT_WIDTH // divisor}:{SHOT_HEIGHT // divisor}"
    if size is None:
        return f"screens/{name}: not a PNG image, expected ratio {expected}"
    width, height = size
    if height == 0 or abs(width / height - SHOT_WIDTH / SHOT_HEIGHT) > SHOT_TOLERANCE * SHOT_WIDTH / SHOT_HEIGHT:
        return f"screens/{name}: {width}x{height} is not at the ratio {expected} (tolerance {SHOT_TOLERANCE:.1%})"
    if width < SHOT_WIDTH:
        return f"screens/{name}: {width}x{height} is narrower than {SHOT_WIDTH} px (ratio {expected})"
    return None


def screen_files(assets, errors):
    """{name: bytes} of the images of the assets, each checked at the capture ratio. RQ-WEB-003, RQ-WEB-012,
    RQ-WEB-019, DEC-WEB-007"""
    files = {path.name: path.read_bytes() for path in sorted((Path(assets) / SCREENS).iterdir()) if path.is_file()}
    errors.extend(error for error in (screen_size_error(name, data) for name, data in files.items()) if error)
    return files


def write_site(out, page, screens, demo_files):
    """Writes index.html, screens/ and demo/ into the folder, replacing them, and touches nothing else. RQ-WEB-001,
    DEC-WEB-006"""
    out = Path(out)
    out.mkdir(parents=True, exist_ok=True)
    (out / PAGE).write_text(page, encoding=ENCODING)
    for folder, files in ((SCREENS, screens), (DEMO_FOLDER, demo_files)):
        shutil.rmtree(out / folder, ignore_errors=True)
        (out / folder).mkdir()
        for name, data in files.items():
            (out / folder / name).write_bytes(data)


def main(argv=None):
    """Parse the arguments, build in memory, then write the site, or report the errors and write nothing. RQ-WEB-001,
    RQ-WEB-002"""
    parser = argparse.ArgumentParser(prog="agnos-meta-website", description="Build the AGNOS presentation website.")
    commands = parser.add_subparsers(dest="command", required=True)
    build = commands.add_parser("build", help="build the site into a folder")
    build.add_argument("--demo", required=True, help="the demo repository, whose Performance Center is generated")
    build.add_argument("--out", required=True, help="the folder to write the site into")
    build.add_argument("--demo-page", help=f"a demo {DEMO_PAGE_NAME} to copy instead of generating it")
    args = parser.parse_args(argv)
    errors = []
    result = build_page(ASSETS_DIR, errors)
    demo_files = {}
    if args.demo_page:
        demo_files = given_demo_page(args.demo_page, errors)
    elif not errors:
        demo_files = generated_demo_page(args.demo, errors)
    screens = screen_files(ASSETS_DIR, errors)
    if result is None or errors:
        for error in errors:
            print(REPORT + error, file=sys.stderr)
        return 1
    page, summary = result
    write_site(args.out, page, screens, demo_files)
    origin = DEMO_COPIED if args.demo_page else DEMO_GENERATED
    print(f"{REPORT}{summary}, demo page {origin}; {args.out} written")
    return 0


if __name__ == "__main__":
    sys.exit(main())
